#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Valores que NAO sao segredo ficam num arquivo fora do repositorio; segredos NUNCA sao gravados em arquivo (so no GitHub, via set_secret).
# (a biblioteca ja definiu ENV_FILE=".env"; aqui trocamos de proposito, senao os valores iriam para a pasta onde o assistente for executado)
ENV_FILE="${CUIDAR_ENV_FILE:-$HOME/.cuidar-em-casa-backup.env}"
AQUI="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"            # .../backup
MODELO="$AQUI/repositorio-privado"
SQL_ROLE="$AQUI/sql/backup_ro.sql"
PROJECT_REF_PADRAO="ynbqblvdtgwabczbssfp"
PASTA_BASE="${PASTA_BASE:-$HOME}"                                  # onde o repositorio privado fica no seu computador (nunca dentro do repositorio do projeto)
CHAVE_ARQ="${CHAVE_ARQ:-$HOME/cuidar-em-casa-chave-privada-backup.txt}"

# copiar "texto" coloca na area de transferencia (sem mostrar na tela). Retorna erro se nao houver ferramenta.
copiar() {
  if   command -v clip.exe >/dev/null 2>&1; then printf '%s' "$1" | clip.exe
  elif command -v pbcopy   >/dev/null 2>&1; then printf '%s' "$1" | pbcopy
  elif command -v wl-copy  >/dev/null 2>&1; then printf '%s' "$1" | wl-copy
  elif command -v xclip    >/dev/null 2>&1; then printf '%s' "$1" | xclip -selection clipboard
  else return 1; fi
}
# Acha o age mesmo logo depois de instalar pelo winget (o PATH so atualiza em terminal novo).
achar_age() {
  command -v age >/dev/null 2>&1 && command -v age-keygen >/dev/null 2>&1 && return 0
  local d f
  for d in "${LOCALAPPDATA:-}"/Microsoft/WinGet/Packages/FiloSottile.age_*; do
    [[ -d "$d" ]] || continue
    f="$(find "$d" -name 'age.exe' 2>/dev/null | head -n1)"
    [[ -n "$f" ]] && PATH="$PATH:$(dirname "$f")" && command -v age >/dev/null 2>&1 && return 0
  done
  return 1
}

TOTAL_STAGES=9

banner "Backup automático do Cuidar em Casa"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Ferramentas"
say "O backup roda sozinho no GitHub, todo dia às 02:30, e fica cifrado: só a SUA chave abre."
say "Vamos conferir o que este computador precisa ter."
for c in git gh openssl; do
  if command -v "$c" >/dev/null 2>&1; then say "✓ $c"; else warn "falta o $c. Instale e rode o assistente de novo."; exit 1; fi
done
if gh auth status >/dev/null 2>&1; then say "✓ gh (GitHub) entrou na sua conta"; else
  warn "o gh ainda não entrou na sua conta do GitHub."
  step "Rode: gh auth login   (escolha GitHub.com, HTTPS, e entre pelo navegador)"
  pause "Depois de entrar, aperte Enter."
  gh auth status >/dev/null 2>&1 || { warn "ainda sem login no GitHub. Abortando."; exit 1; }
fi
if achar_age; then say "✓ age (programa de cifragem)"; else
  warn "falta o 'age', o programa que cria a chave e abre os backups."
  if command -v winget >/dev/null 2>&1; then
    if confirm "Instalar agora com o winget (FiloSottile.age)?"; then
      winget install --id FiloSottile.age -e --accept-source-agreements --accept-package-agreements || true
      achar_age || { warn "instalei, mas este terminal ainda não enxerga. Feche e abra o terminal e rode o assistente de novo."; exit 1; }
      say "✓ age instalado"
    else warn "sem o age não dá para continuar."; exit 1; fi
  else
    step "Instale o age: https://github.com/FiloSottile/age/releases (e rode o assistente de novo)."; exit 1
  fi
fi
if command -v docker >/dev/null 2>&1 && docker info >/dev/null 2>&1; then say "✓ Docker em execução (permite testar a conexão e o ensaio de restauração)"; else
  note "Docker não está em execução: o teste de conexão e o ensaio de restauração (etapa 9) precisarão dele ou de um PostgreSQL 17 instalado."
fi
pause "Tudo certo aqui? Enter para continuar."

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Repositório PRIVADO só para os backups"
warn "O repositório do projeto é PÚBLICO. Os backups NUNCA podem ir para lá."
OWNER="$(gh api user --jq .login)"
ask REPO_NOME "Nome do repositório privado [cuidar-em-casa-backups]:"
REPO_NOME="${REPO_NOME:-cuidar-em-casa-backups}"
write_env REPO_NOME "$REPO_NOME"
if gh repo view "$OWNER/$REPO_NOME" >/dev/null 2>&1; then
  say "O repositório $OWNER/$REPO_NOME já existe; vamos reaproveitá-lo."
else
  confirm "Criar o repositório PRIVADO $OWNER/$REPO_NOME na sua conta?" || { warn "sem o repositório não dá para continuar."; exit 1; }
  gh repo create "$OWNER/$REPO_NOME" --private --description "Backups cifrados do Cuidar em Casa (privado)" >/dev/null
fi
[[ "$(gh repo view "$OWNER/$REPO_NOME" --json isPrivate --jq .isPrivate)" == "true" ]] || { warn "ATENÇÃO: $OWNER/$REPO_NOME NÃO é privado. Torne-o privado e rode de novo. Abortando."; exit 1; }
say "✓ confirmado: o repositório é privado (pasta no seu computador: $PASTA_BASE/$REPO_NOME)"
PASTA_REPO="$PASTA_BASE/$REPO_NOME"
if [[ -d "$PASTA_REPO/.git" ]]; then (cd "$PASTA_REPO" && git pull -q --ff-only 2>/dev/null || true); else gh repo clone "$OWNER/$REPO_NOME" "$PASTA_REPO" >/dev/null 2>&1; fi
cd "$PASTA_REPO"      # daqui para frente o gh e o git falam com ESTE repositório (os segredos vão para ele)
[[ "$(gh repo view --json nameWithOwner --jq .nameWithOwner)" == "$OWNER/$REPO_NOME" ]] || { warn "a pasta não aponta para $OWNER/$REPO_NOME. Abortando."; exit 1; }
cp -R "$MODELO/." .
git add -A
if git diff --cached --quiet; then say "Os arquivos do agendador já estavam no repositório."; else
  git -c user.name="${OWNER}" -c user.email="${OWNER}@users.noreply.github.com" commit -q -m "Agendador do backup (v19)"
  git push -q origin HEAD
  say "✓ agendador e scripts enviados para o repositório privado"
fi
pause "Enter para continuar."

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "A chave que abre os backups (a etapa mais importante)"
warn "SE ESTA CHAVE SE PERDER, TODOS OS BACKUPS FICAM INÚTEIS. Se for roubada junto com os arquivos, os dados ficam expostos."
if [[ -f "$CHAVE_ARQ" ]]; then
  say "Já existe uma chave em $CHAVE_ARQ; vamos reaproveitá-la (não vou sobrescrever)."
else
  age-keygen -o "$CHAVE_ARQ" 2>/dev/null; chmod 600 "$CHAVE_ARQ" 2>/dev/null || true
  say "✓ chave criada em $CHAVE_ARQ"
fi
CHAVE_PUBLICA="$(age-keygen -y "$CHAVE_ARQ")"
say "Chave pública (não é segredo): $CHAVE_PUBLICA"
step "Abra o arquivo da chave e copie a linha que começa com AGE-SECRET-KEY-:"
note "$CHAVE_ARQ"
if confirm "Abrir o arquivo agora no Bloco de Notas?"; then (notepad "$(cygpath -w "$CHAVE_ARQ" 2>/dev/null || echo "$CHAVE_ARQ")" >/dev/null 2>&1 &) || xdg-open "$CHAVE_ARQ" >/dev/null 2>&1 || true; fi
step "Guarde essa linha em DOIS lugares diferentes: no seu gerenciador de senhas E escrita em papel, num lugar seguro."
note "Não mande por e-mail ou mensagem e não salve na nuvem sem proteção. Nunca coloque no GitHub."
GUARDEI=""
while [[ "$GUARDEI" != "guardei em dois lugares" ]]; do
  ask GUARDEI "Quando tiver guardado, digite exatamente: guardei em dois lugares"
done
set_secret BACKUP_AGE_PUBLIC_KEY "$CHAVE_PUBLICA"        # a PÚBLICA: só serve para cifrar

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Usuário de leitura no Supabase (só para o backup)"
say "Vamos criar no banco um usuário que só LÊ. Ele não consegue escrever nem apagar nada."
ask PROJECT_REF "Código do projeto Supabase [$PROJECT_REF_PADRAO]:"
PROJECT_REF="${PROJECT_REF:-$PROJECT_REF_PADRAO}"
[[ "$PROJECT_REF" =~ ^[a-z0-9]{20}$ ]] || { warn "código de projeto inesperado (esperava 20 letras/números). Abortando."; exit 1; }
write_env PROJECT_REF "$PROJECT_REF"
SENHA_BACKUP="$(openssl rand -hex 24)"                    # só existe na memória deste assistente e, depois, no segredo do GitHub
SQL_PRONTO="$(sed "s/__SENHA__/$SENHA_BACKUP/g" "$SQL_ROLE")"
open_url "https://supabase.com/dashboard/project/$PROJECT_REF/sql/new"
step "No editor SQL que abriu, apague o que houver e COLE (Ctrl+V) o comando que já está na sua área de transferência."
if copiar "$SQL_PRONTO"; then say "✓ comando copiado (a senha do backup está dentro dele; ela não aparece na tela)"; else
  warn "não consegui copiar sozinho. Vou mostrar o comando; ele contém a senha, então feche a janela depois:"
  printf '\n%s\n\n' "$SQL_PRONTO"
fi
step "Clique em Run. O resultado esperado é: Success. No rows returned."
confirm "Rodou sem erro?" || { warn "Sem isso o backup não consegue ler o banco. Rode o assistente de novo quando resolver."; exit 1; }
copiar "" || true     # limpa a área de transferência

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Endereço do banco para o backup"
say "O GitHub só consegue falar com o banco pelo 'Session pooler' (o endereço direto do plano gratuito não funciona lá)."
open_url "https://supabase.com/dashboard/project/$PROJECT_REF?showConnect=true&method=session"
step "Na janela Connect, em 'Session pooler', ache o endereço (host), parecido com: aws-0-sa-east-1.pooler.supabase.com"
step "Copie SÓ o endereço (a parte depois do @ e antes de :5432)."
ask DB_HOST "Endereço (host) do Session pooler:"
DB_HOST="${DB_HOST//[[:space:]]/}"
[[ "$DB_HOST" =~ ^[a-z0-9.-]+\.pooler\.supabase\.com$ ]] || { warn "não parece um endereço do pooler do Supabase (termina em .pooler.supabase.com). Abortando."; exit 1; }
write_env DB_HOST "$DB_HOST"
BACKUP_DB_URL="postgresql://backup_ro.${PROJECT_REF}:${SENHA_BACKUP}@${DB_HOST}:5432/postgres?sslmode=require"
if command -v docker >/dev/null 2>&1 && docker info >/dev/null 2>&1; then
  say "Testando a conexão agora (com o Docker)..."
  if BK_URL="$BACKUP_DB_URL" docker run --rm -e BK_URL postgres:17 sh -c 'psql "$BK_URL" -X -At -c "select current_user"' 2>/dev/null | grep -q '^backup_ro$'; then
    say "✓ conectou como backup_ro"
  else
    warn "não consegui conectar como backup_ro. Confira o endereço e se o comando da etapa anterior rodou. (A senha do pooler pode levar um minuto para valer.)"
    confirm "Continuar mesmo assim (o teste de verdade será o primeiro backup)?" || exit 1
  fi
else
  note "Sem Docker, o teste de conexão fica para o primeiro backup (etapa 7)."
fi

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Segredos e retenção no GitHub"
say "Guardando no repositório privado o que o agendador precisa. Nada disso vai para arquivo no seu computador."
set_secret BACKUP_DB_URL "$BACKUP_DB_URL"
ask RETENCAO "Por quantos dias guardar cada backup? [30]:"
RETENCAO="${RETENCAO:-30}"
[[ "$RETENCAO" =~ ^[0-9]+$ ]] && (( RETENCAO >= 1 && RETENCAO <= 90 )) || { warn "use um número de 1 a 90."; exit 1; }
set_var BACKUP_RETENCAO_DIAS "$RETENCAO"
unset SENHA_BACKUP SQL_PRONTO

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Primeiro backup de verdade"
say "Vamos mandar o GitHub fazer um backup agora, para ver funcionando."
ANTES="$(gh run list --workflow backup.yml --limit 1 --json databaseId --jq '.[0].databaseId // 0')"
DISPAROU=""
for _ in $(seq 1 20); do if gh workflow run backup.yml >/dev/null 2>&1; then DISPAROU=1; break; fi; sleep 3; done
[[ -n "$DISPAROU" ]] || { warn "o GitHub ainda não enxergou o fluxo do backup. Espere um minuto e rode o assistente de novo."; exit 1; }
ID=""
for _ in $(seq 1 30); do
  sleep 3; ID="$(gh run list --workflow backup.yml --limit 1 --json databaseId --jq '.[0].databaseId // 0')"
  [[ "$ID" != "$ANTES" && "$ID" != "0" ]] && break
done
[[ -n "$ID" && "$ID" != "$ANTES" ]] || { warn "não achei a execução. Veja em: gh run list --workflow backup.yml"; exit 1; }
say "Execução $ID iniciada. Acompanhando (leva uns 2 minutos)..."
if gh run watch "$ID" --exit-status >/dev/null 2>&1; then say "✓ backup concluído"; else
  warn "o backup falhou. Últimas linhas do registro:"
  gh run view "$ID" --log-failed 2>/dev/null | tail -25 || true
  exit 1
fi
rm -rf recebido; mkdir -p recebido
gh run download "$ID" -D recebido >/dev/null
ARQ_BK="$(find recebido -name '*.age' | head -n1)"
[[ -s "$ARQ_BK" ]] || { warn "o arquivo do backup não veio. Abortando."; exit 1; }
say "✓ arquivo recebido: $(basename "$ARQ_BK") ($(wc -c < "$ARQ_BK") bytes, cifrado)"
git pull -q --ff-only 2>/dev/null || true

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Conferir que a SUA chave abre o backup"
say "Abrindo o backup com a chave que está neste computador (só para ver o conteúdo, sem restaurar nada)."
if age -d -i "$CHAVE_ARQ" "$ARQ_BK" | tar -xzO contagens.txt > recebido/contagens.txt 2>/dev/null && [[ -s recebido/contagens.txt ]]; then
  say "✓ a chave abriu o backup. Linhas por tabela:"
  sed 's/^/      /' recebido/contagens.txt
else warn "a chave NÃO abriu o backup. Não confie neste backup até resolver."; exit 1; fi
rm -rf recebido

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Ensaio de restauração (muito recomendado)"
warn "Um backup que nunca foi restaurado ainda não é garantia. Vamos restaurar num projeto DESCARTÁVEL."
if confirm "Fazer o ensaio agora (uns 10 minutos)?"; then
  open_url "https://supabase.com/dashboard/new/qxsjlvdouxqatlkixbvf"
  step "Crie um projeto novo chamado cuidar-em-casa-restauracao-teste (plano gratuito, região South America)."
  step "Anote a senha do banco que você escolher."
  pause "Quando o projeto terminar de ser criado, aperte Enter."
  step "No projeto NOVO, clique em Connect → 'Session pooler' e copie a URL de conexão (começa com postgresql://)."
  ask_secret DESTINO_URL "Cole a URL de conexão do projeto de TESTE (a senha fica oculta):"
  [[ "$DESTINO_URL" == postgresql://* ]] || { warn "isso não parece uma URL postgresql://"; exit 1; }
  export DESTINO_URL
  [[ "$DESTINO_URL" != *"$PROJECT_REF"* ]] || { warn "ATENÇÃO: essa URL é do projeto de PRODUÇÃO ($PROJECT_REF). Use o projeto de teste. Abortando."; exit 1; }
  ARQ_BK="$(gh run download "$ID" -D recebido >/dev/null 2>&1; find recebido -name '*.age' | head -n1)"
  if command -v docker >/dev/null 2>&1 && docker info >/dev/null 2>&1; then
    docker build -q -t bk-cliente:17 - >/dev/null <<'DOCKERFILE'
FROM postgres:17
RUN apt-get update -qq && apt-get install -y -qq age >/dev/null && rm -rf /var/lib/apt/lists/*
DOCKERFILE
    WORK_WIN="$(cd . && (pwd -W 2>/dev/null || pwd))"
    if MSYS_NO_PATHCONV=1 docker run --rm -e DESTINO_URL -v "$WORK_WIN:/work" -v "$(cd "$(dirname "$CHAVE_ARQ")" && (pwd -W 2>/dev/null || pwd)):/chave:ro" -w /work bk-cliente:17 \
         bash -c 'bash scripts/restaurar.sh "$0" "$1" "$DESTINO_URL"' "/work/$ARQ_BK" "/chave/$(basename "$CHAVE_ARQ")"; then
      say "✓ RESTAURAÇÃO FUNCIONOU. Confira no painel do projeto de teste: Table Editor e Authentication → Users."
      step "Opcional: no app, aponte para o projeto de teste e use 'Esqueci a senha' para ver se uma conta entra."
      confirm "Já pode apagar o projeto de teste no painel (Settings → General → Delete project)?" || true
    else
      warn "a restauração FALHOU. O backup ainda não é de confiança. Veja a mensagem acima."; SKIPPED+=("ensaio de restauração falhou: o backup NÃO foi validado")
    fi
  else
    warn "sem Docker não consigo rodar a restauração daqui."
    note "Rode no PowerShell/terminal com PostgreSQL 17 e age:  scripts/restaurar.sh ARQUIVO.age CHAVE.txt URL_DE_TESTE"
    SKIPPED+=("ensaio de restauração (precisa de Docker ou PostgreSQL 17): o backup ainda NÃO foi validado")
  fi
  rm -rf recebido
else
  SKIPPED+=("ensaio de restauração: o backup ainda NÃO foi validado. Faça nas próximas semanas (backup/README.md).")
fi

say ""
say "Backup configurado: todo dia às 02:30 (Brasília), guardado por ${RETENCAO} dias, cifrado."
note "Onde ver: aba Actions do repositório $OWNER/$REPO_NOME. Se uma execução falhar, o GitHub avisa por e-mail."
note "Lembretes: (1) a chave privada em DOIS lugares; (2) teste a restauração a cada 3 meses; (3) se um dia desconfiar da senha, rode este assistente de novo: ele troca a senha."
if confirm "Apagar o arquivo da chave privada deste computador? (só diga sim se ela já está nos dois lugares seguros)"; then rm -f "$CHAVE_ARQ"; say "apagado."; fi

finish
